// coverage map: draws window.CAMS (generated by generate.py) with MapLibre.
(() => {
    const container = document.getElementById('coverage-map');

    if (!container) {
        return;
    }
    if (!window.maplibregl || !window.CAMS) {
        container.classList.add('d-flex', 'align-items-center', 'justify-content-center', 'text-secondary', 'p-3', 'text-center');
        container.textContent = 'the map could not load. check your connection and reload the page.';
        return;
    }

    const raw = window.CAMS.data;
    const stride = window.CAMS.fields.length; // lat, lng, limit, osm_node
    const total = raw.length / stride;

    const features = new Array(total);
    for (let i = 0, j = 0; i < total; i++, j += stride) {
        features[i] = {
            type: 'Feature',
            geometry: { type: 'Point', coordinates: [raw[j + 1], raw[j]] },
            properties: { limit: raw[j + 2], node: raw[j + 3] },
        };
    }

    const map = new maplibregl.Map({
        container,
        style: 'https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json',
        center: [15, 45],
        zoom: 1.4,
        minZoom: 1,
        maxZoom: 18,
        dragRotate: false,
        touchPitch: false,
        cooperativeGestures: matchMedia('(pointer: coarse)').matches,
    });

    map.addControl(new maplibregl.NavigationControl({ showCompass: false }), 'top-right');
    map.addControl(new maplibregl.GeolocateControl({
        positionOptions: { enableHighAccuracy: false },
        fitBoundsOptions: { maxZoom: 11 },
        trackUserLocation: false,
        showUserLocation: true,
    }), 'top-right');
    map.addControl(new maplibregl.FullscreenControl(), 'top-right');
    map.addControl(new maplibregl.ScaleControl({ maxWidth: 100, unit: 'metric' }), 'bottom-left');

    map.on('load', () => {
        map.addSource('cameras', { type: 'geojson', data: { type: 'FeatureCollection', features } });
        map.addLayer({
            id: 'cameras',
            type: 'circle',
            source: 'cameras',
            paint: {
                'circle-radius': ['interpolate', ['linear'], ['zoom'], 1, 1.2, 4, 2, 8, 3, 12, 5, 16, 8],
                'circle-color': '#38bdf8',
                'circle-opacity': 0.85,
                'circle-stroke-color': '#0ea5e9',
                'circle-stroke-width': 0.4,
            },
        });

        map.on('click', 'cameras', (e) => {
            const f = e.features[0];
            const { limit, node } = f.properties;
            const html = `
                <div class="fw-semibold mb-1">speed camera</div>
                <div class="mb-2">${limit ? `limit ${limit}` : 'limit not mapped'}</div>
                <a href="https://www.openstreetmap.org/node/${node}" target="_blank" rel="noopener">view or fix on OpenStreetMap ↗</a>`;
            new maplibregl.Popup({ maxWidth: '260px' }).setLngLat(f.geometry.coordinates).setHTML(html).addTo(map);
        });
        map.on('mouseenter', 'cameras', () => { map.getCanvas().style.cursor = 'pointer'; });
        map.on('mouseleave', 'cameras', () => { map.getCanvas().style.cursor = ''; });
    });
})();
